def extract_en_keywords(meaning):
    """从含义里抽英文关键词（前 2-3 个）"""
    if not meaning: return None
    words = re.findall(r"\b[a-zA-Z]{4,}\b", meaning)
    stop = {"adj", "noun", "verb", "and", "the", "for", "from", "with", "that", "this",
            "have", "been", "such", "also", "into", "than"}
